package mx.transcriptor.studio;
import java.util.*;import java.util.regex.*;
public final class TextTools {
 public static final class Protection {public String masked;public LinkedHashMap<String,String> values=new LinkedHashMap<>();public List<String> problems(String output){List<String> out=new ArrayList<>();for(String token:values.keySet())if(count(masked,token)!=count(output,token))out.add("Cambió o desapareció: "+values.get(token));Matcher m=Pattern.compile("ZXQKEEP[A-Z0-9]+QXZ").matcher(output);while(m.find())if(!values.containsKey(m.group()))out.add("Referencia desconocida: "+m.group());return out;}public String restore(String output){for(Map.Entry<String,String> e:values.entrySet())output=output.replace(e.getKey(),e.getValue());return output;}}
 static int count(String text,String part){int n=0,p=0;while((p=text.indexOf(part,p))>=0){n++;p+=part.length();}return n;}
 public static Protection protect(String text,List<String> names){Protection p=new Protection();List<String> terms=new ArrayList<>();for(String n:names)if(n!=null&&!n.trim().isEmpty()&&text.contains(n.trim()))terms.add(n.trim());Matcher dates=Pattern.compile("(?iu)\\b\\d{1,2}\\s+de\\s+(?:enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)(?:\\s+de\\s+\\d{4})?\\b").matcher(text);while(dates.find())terms.add(dates.group());Matcher nums=Pattern.compile("[\\p{Sc}]?\\d+(?:[.,:/-]\\d+)*(?:\\s?%)?").matcher(text);while(nums.find())terms.add(nums.group());terms=new ArrayList<>(new LinkedHashSet<>(terms));terms.sort((a,b)->Integer.compare(b.length(),a.length()));String prefix="ZXQKEEP";while(text.contains(prefix))prefix+="X";StringBuilder regex=new StringBuilder();for(String t:terms){if(regex.length()>0)regex.append('|');regex.append(Pattern.quote(t));}p.masked=text;if(regex.length()==0)return p;Matcher m=Pattern.compile(regex.toString()).matcher(text);StringBuffer s=new StringBuffer();int id=0;while(m.find()){String token=prefix+(id++)+"QXZ";p.values.put(token,m.group());m.appendReplacement(s,token);}m.appendTail(s);p.masked=s.toString();return p;}
 public static String replace(String text,String from,String to,boolean whole,boolean sensitive){if(from==null||from.isEmpty())throw new IllegalArgumentException("El texto a buscar está vacío");String p=Pattern.quote(from);if(whole)p="(?<![\\p{L}\\p{N}_])"+p+"(?![\\p{L}\\p{N}_])";return Pattern.compile(p,sensitive?0:Pattern.CASE_INSENSITIVE|Pattern.UNICODE_CASE).matcher(text).replaceAll(Matcher.quoteReplacement(to));}
 public static List<String> chunks(String text,int max){List<String> out=new ArrayList<>();while(text.length()>max){int end=max;if(Character.isHighSurrogate(text.charAt(end-1)))end--;int candidate=text.lastIndexOf('\n',end);if(candidate<end/2)candidate=text.lastIndexOf(". ",end);if(candidate<end/2)candidate=text.lastIndexOf(' ',end);if(candidate>end/2)end=candidate+1;out.add(text.substring(0,end));text=text.substring(end);}if(!text.isEmpty())out.add(text);return out;}
}
